per_call.cmd:
python3 - <<'EOF'
import pandas as pd, re
df = pd.read_parquet("/app/work/default.parquet")
md = pd.read_parquet("/app/work/metadata.parquet")

def norm(s):
    return re.sub(r"\s+", " ", s).strip()

norm_probs = {norm(p): i for i, p in enumerate(md["problem"])}
matched = 0; unmatched = 0
import collections
unmatched_prefixes = collections.Counter()
for i, row in df.iterrows():
    u = norm(row["conversations"][0]["value"])
    hit = None
    for np_, mi in norm_probs.items():
        if np_ in u:
            hit = mi; break
    if hit is None:
        unmatched += 1
        unmatched_prefixes[u[:80]] += 1
    else:
        matched += 1
print("matched:", matched, "unmatched:", unmatched)
for k, v in unmatched_prefixes.most_common(5):
    print("UNMATCHED PREFIX:", repr(k))
EOF
